Arrange() {
        BlockContainer container = new BlockContainer(new BorderArrangement());
        Rectangle2D rectangle = new Rectangle2D.Double(1.0, 2.0, 3.0, 4.0);
        container.add(rectangle, "A");
        Rectangle2D rectangle2 = new Rectangle2D.Double(11.0, 22.0, 33.0, 44.0);
        container.add(rectangle2, "B");
        Rectangle2D rectangle3 = new Rectangle2D.Double(111.0, 222.0, 333.0, 444.0);
        container.add(rectangle3, "C");
        assertEquals(rectangle, container.getInsets().get(RectangleEdge.LEFT), 0.0);
        assertEquals(rectangle2, container.getInsets().get(RectangleEdge.RIGHT), 0.0);
        assertEquals(rectangle3, container.getInsets().get(RectangleEdge.TOP), 0.0);
        assertEquals(rectangle3, container.getInsets().get(RectangleEdge.BOTTOM), 0.0);
        assertEquals(1.0, container.getInsets().get(RectangleEdge.CENTER) / 2.0, 0.0);
        assertEquals(new Rectangle2D.Double(1.0, 2.0, 3.0, 4.0), container.getInsets());
    }

