Arrange() {
        BlockContainer container = new BlockContainer(new BorderArrangement());
        RectangleConstraint constraint = new RectangleConstraint(
                new Range(0.0, 0.0), null, LengthConstraintType.FIXED,
                0.0, null, LengthConstraintType.NONE);
        Size2D size = new Size2D(10.0, 5.0);
        container.add(new TestBlock(size, constraint));
        assertThat(container.arrange(null, RectangleConstraint.NONE),
                is(size));
        assertThat(container.getSize(), is(size));
        assertThat(container.arrange(null), is(size));
        assertThat(container.findBlock(RectangleEdge.LEFT), is(container.getLeftBlock()));
        assertThat(container.findBlock(RectangleEdge.RIGHT), is(container.getRightBlock()));
        assertThat(container.findBlock(RectangleEdge.TOP), is(container.getTopBlock()));
        assertThat(container.findBlock(RectangleEdge.BOTTOM), is(container.getBottomBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.LEFT, RectangleEdge.RIGHT)), is(container.getLeftBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.TOP, RectangleEdge.BOTTOM)), is(container.getTopBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.LEFT, RectangleEdge.TOP)), is(container.getLeftBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.RIGHT, RectangleEdge.BOTTOM)), is(container.getRightBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.LEFT, RectangleEdge.RIGHT)), is(container.getRightBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.TOP, RectangleEdge.BOTTOM)), is(container.getBottomBlock()));
        assertThat(container.findBlock(new RectangleEdge(
                RectangleEdge.RIGHT, RectangleEdge.TOP)), is(container.getBottomBlock()));
    }

