Arrange() {
        BlockContainer container = new BlockContainer(new BorderArrangement());
        RectangleConstraint constraint = new RectangleConstraint(
                new Range(0.0, 0.0), new Range(0.0, 0.0),
                LengthConstraintType.NONE, 0.0, null,
                LengthConstraintType.FIXED);
        container.add(new EmptyBlock(constraint));
        Size2D size = container.arrange(null, constraint);
        assertThat(size, is(equalTo(new Size2D(0.0, 0.0))));
        container.clear();
        container.add(new EmptyBlock(constraint));
        container.add(new EmptyBlock(constraint));
        container.add(new EmptyBlock(constraint));
        size = container.arrange(null, constraint);
        assertThat(size, is(equalTo(new Size2D(0.0, 2.0))));
    }
